window.RP_SESSION={"id":"S-365a78775679","messages":[{"id":"RP-III-0055803","time":"2026-03-27T10:57:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"...\n...\n...","characters":["P-cca78a891e49"]},{"id":"RP-III-0055804","time":"2026-03-27T10:57:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"장작을 한참 패던 뮤리엘은 어느샌가 밤을 새바렸다는 사실을 깨달았다.","characters":["P-cca78a891e49"]},{"id":"RP-III-0055805","time":"2026-03-27T10:58:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"\" 벌써 시간이 이렇게 되었... \"","characters":["P-cca78a891e49"]},{"id":"RP-III-0055806","time":"2026-03-27T10:58:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-cca78a891e49"]},{"id":"RP-III-0055807","time":"2026-03-27T10:58:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'뮤리엘'의 힘 판정 :\n[7] + [2] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0055808","time":"2026-03-27T10:58:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"\" 나! \"\n쩍 하고 나무가 다시 동강 쪼개졌다.","characters":["P-cca78a891e49"]},{"id":"RP-III-0055809","time":"2026-03-27T10:59:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"흐른 땀을 닦아내며, 수북히 쌓인 나무를 가만히 바라보았다.","characters":["P-cca78a891e49"]},{"id":"RP-III-0055810","time":"2026-03-27T11:04:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"상념처럼 피어오른 것은 어젯 밤 마리아가 보여준 모습이었다. 말괄량이에 주정뱅이에 말도 지지리도 안듣지만 퍽 귀여운 동생 같아 마음이 쓰이던 이였는데.","characters":["P-cca78a891e49"]},{"id":"RP-III-0055811","time":"2026-03-27T11:05:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"조바라고 했나, 그 자 얼굴만 떠올려도 홍당무처럼 얼굴을 붉히고 말을 더듬는게 첫사랑도 아직인 소녀처럼 구는 것이 아닌가.","characters":["P-cca78a891e49"]},{"id":"RP-III-0055812","time":"2026-03-27T11:06:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"마리라는 기사도 그러했다. 투구 속에서 소속감조차 느끼지 못하고 스스로 방황하던 모습이 기억에 남았는데.","characters":["P-cca78a891e49"]},{"id":"RP-III-0055813","time":"2026-03-27T11:07:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"어느샌가 션이랑 이래저래 잘 맺어진 듯 보였지. 투구도 벗고 행복에 겨운 듯 보였다.","characters":["P-cca78a891e49"]},{"id":"RP-III-0055814","time":"2026-03-27T11:07:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"하물며 지난 번 할버드를 수리하려고 대장간에 들렸을 때....","characters":["P-cca78a891e49"]},{"id":"RP-III-0055815","time":"2026-03-27T11:07:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"\" ... ... \"","characters":["P-cca78a891e49"]},{"id":"RP-III-0055816","time":"2026-03-27T11:07:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-cca78a891e49"]},{"id":"RP-III-0055817","time":"2026-03-27T11:07:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'뮤리엘'의 힘 판정 :\n[2] + [2] = [4]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-III-0055818","time":"2026-03-27T11:08:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"충동적으로 도끼를 휘둘렀지만 애꿎은 땅만 내리 찍었다.","characters":["P-cca78a891e49"]},{"id":"RP-III-0055819","time":"2026-03-27T11:09:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"여행길에 떠난 이후 어디에 소속된 적이 처음이라. 동료들의 관계가 변화하는 이 상황이 어딘가 익숙하면서도 멀게만 느껴졌다.","characters":["P-cca78a891e49"]},{"id":"RP-III-0055820","time":"2026-03-27T11:12:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"배에서는 이따금 다른 선원들이 여자들을 끈적한 시선으로 쳐다보거나, 추잡한 추파를 던지며. \n싸구려 럼주가 바닥에 굴러다니던 곳이라면 어디든 불순한 이성교제를 심심찮게 발견할 수 있었다. 이러한 풋풋한 관계는 가까운듯 멀게만 느껴지는게 이러한 이유에서였을까.","characters":["P-cca78a891e49"]},{"id":"RP-III-0055821","time":"2026-03-27T11:13:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"\" ... 이거 참, 씻고 잠이나 자야겠군. \"\n상념이 깊어지자 고개를 휘휘 저어내고, 밤새 피로해진 몸을 이끌었다.","characters":["P-cca78a891e49"]},{"id":"RP-III-0055822","time":"2026-03-27T11:15:00+09:00","room":"RP III","name":"뮤리엘","profile":"에일린","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-cca78a891e49"]},{"id":"RP-III-0055823","time":"2026-03-27T11:15:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
